// Create array of items for loop
const scriptCount = $input.first().json.scriptCount;
const items = [];

for (let i = 1; i <= scriptCount; i++) {
  items.push({
    scriptNumber: i,
    researchDocument: $input.first().json.researchDocument,
    scriptLength: $input.first().json.scriptLength,
    targetWordCount: $input.first().json.targetWordCount,
    selectedAngles: $input.first().json.selectedAngles
  });
}

return items;

// Aggregate all generated scripts
const allScripts = $input.all();

let compiledDocument = `# UGC SCRIPTS COMPILATION\n\n`;
compiledDocument += `**Generated:** ${new Date().toISOString()}\n`;
compiledDocument += `**Total Scripts:** ${allScripts.length}\n`;
compiledDocument += `**Script Length:** ${allScripts[0].json.scriptLength}\n\n`;
compiledDocument += `---\n\n`;

// Add each script
allScripts.forEach(item => {
  compiledDocument += item.json.scriptContent + '\n\n';
  compiledDocument += '═'.repeat(80) + '\n\n';
});

return {
  compiledScripts: compiledDocument,
  scriptCount: allScripts.length,
  scriptLength: allScripts[0].json.scriptLength,
  scripts: allScripts.map(item => ({
    number: item.json.scriptNumber,
    content: item.json.scriptContent,
    generatedAt: item.json.generatedAt
  }))
};
